# ---- your weights (28 Sep, third revision): job = salary = English, cost 15 ----
W_JOB = W_SAL = W_ENG = 85 / 3          # 28.33 % each
W_COST = 15.0
WEIGHTS = [W_JOB, W_SAL, W_ENG, W_COST]


def pn(x):
    """Persian digits, one decimal, '.0' trimmed: 67.0 → ۶۷, 60.3 → ۶۰.۳"""
    t = f"{x:.1f}".rstrip("0").rstrip(".")
    return t.translate(str.maketrans("0123456789", "۰۱۲۳۴۵۶۷۸۹"))


def wscore(job, sal, eng, cost, w=None):
    """Weighted score 0–100, rounded half-up to one decimal exactly like the Excel formula in block ب."""
    w = w or WEIGHTS
    x = (w[0] * job + w[1] * sal + w[2] * eng + w[3] * cost) / sum(w) * 10
    return int(x * 10 + 0.5) / 10


def rank_txt(pairs):
    """[(name, score), …] → 'A ۷۱.۵ › B = C ۶۰.۳ › …' (ties share one number)."""
    out, i = [], 0
    pairs = sorted(pairs, key=lambda t: -t[1])
    while i < len(pairs):
        j = i
        while j + 1 < len(pairs) and pairs[j + 1][1] == pairs[i][1]:
            j += 1
        out.append(" = ".join(n for n, _ in pairs[i:j + 1]) + " " + pn(pairs[i][1]))
        i = j + 1
    return " › ".join(out)


