def find_prog(uni_sub, prog_sub):
    for p in PROGRAMS:
        if uni_sub in p[1] and prog_sub in p[3]:
            return p
    raise KeyError((uni_sub, prog_sub))


wsD = wb.create_sheet("تصمیم")
wsD.sheet_view.rightToLeft = True
title_font = Font(bold=True, size=14, color="1F4E78")
sec_font = Font(bold=True, size=12, color="FFFFFF")
sec_fill = PatternFill("solid", fgColor="2E75B6")
star_fill = PatternFill("solid", fgColor="FFF2CC")
NC = 11


def section(title):
    r = wsD.max_row + 2
    wsD.cell(row=r, column=1, value=title).font = sec_font
    for c in range(1, NC + 1):
        wsD.cell(row=r, column=c).fill = sec_fill
    wsD.merge_cells(start_row=r, start_column=1, end_row=r, end_column=NC)
    wsD.cell(row=r, column=1).alignment = Alignment(horizontal="right", vertical="center", readingOrder=2)
    return r


def header(cells):
    wsD.append(cells)
    for cell in wsD[wsD.max_row]:
        if cell.value is not None:
            cell.fill, cell.font, cell.alignment, cell.border = hdr_fill, hdr_font, wrap_ctr, border


def para(text, bold=False, height=None):
    r = wsD.max_row + 1
    c = wsD.cell(row=r, column=1, value=text)
    c.alignment = Alignment(wrap_text=True, vertical="top", horizontal="right", readingOrder=2)
    c.font = Font(bold=bold, size=11)
    wsD.merge_cells(start_row=r, start_column=1, end_row=r, end_column=NC)
    wsD.row_dimensions[r].height = height or 34


